1	import { expect, test } from './utils/base';
2	import {
3	    deleteAllMessages,
4	    getMessageDetail,
5	    waitForMessage,
6	} from './utils/mailpit';
7	
8	const extractVerificationLink = (content: string) => {
9	    const hrefMatch =
10	        /href=["']([^"']*\/footy\/auth\/verify\/enquiry\/[^"']*)["']/i.exec(
11	            content,
12	        );
13	    if (hrefMatch?.[1]) return hrefMatch[1];
14	
15	    const textMatch =
16	        /(https?:\/\/[^\s"']*\/footy\/auth\/verify\/enquiry\/[^\s"']+)/i.exec(
17	            content,
18	        );
19	    return textMatch?.[1] ?? null;
20	};
21	
22	test('info page', async ({ page }) => {
23	    const response = await page.goto('/footy/info');
24	    expect(response?.ok()).toBeTruthy();
25	    await expect(page).toHaveURL(/.*info/);
26	    await expect(page).toHaveTitle(/Toastboy FC/);
27	    // await expect(page).toHaveScreenshot('info.png', {
28	    //     mask: [page.locator('iframe[src*="google.com/maps"]')],
29	    // });
30	});
31	
32	test.describe('EnquiryForm', () => {
33	    test('shows validation errors on empty submit', async ({ page }) => {
34	        await page.goto('/footy/info');
35	        const submitButton = page.getByRole('button', { name: 'Send message' });
36	
37	        await submitButton.scrollIntoViewIfNeeded();
38	
39	        await submitButton.click();
40	        await submitButton.scrollIntoViewIfNeeded();
41	        await expect(page.getByText('Name is required')).toBeVisible();
42	        await expect(page.getByText('Invalid email')).toBeVisible();
43	        await expect(page.getByText('Message is required')).toBeVisible();
44	    });
45	
46	    test('shows invalid email error on blur', async ({ page }) => {
47	        await page.goto('/footy/info');
48	        await page.getByRole('textbox', { name: 'Name' }).fill('Test User');
49	        const emailInput = page.getByRole('textbox', { name: 'Email' });
50	        await emailInput.fill('not-an-email');
51	        await page.getByRole('textbox', { name: 'Message' }).click();
52	        const invalidEmailError = page.getByText('Invalid email');
53	        await emailInput.scrollIntoViewIfNeeded();
54	        await expect(invalidEmailError).toBeVisible();
55	    });
56	
57	    test.describe('email flow', () => {
58	        test.describe.configure({ mode: 'serial' });
59	
60	        test.beforeEach(async ({ request }) => {
61	            await deleteAllMessages(request);
62	        });
63	
64	        test.afterEach(async ({ request }) => {
65	            await deleteAllMessages(request);
66	        });
67	
68	        test('submits form and shows confirmation notification', async ({
69	            page,
70	            request,
71	        }) => {
72	            await page.goto('/footy/info');
73	            await page.getByRole('textbox', { name: 'Name' }).fill('Test User');
74	            await page
75	                .getByRole('textbox', { name: 'Email' })
76	                .fill('playwright@example.com');
77	            await page
78	                .getByRole('textbox', { name: 'Message' })
79	                .fill('This is a test enquiry from Playwright.');
80	            await page.getByRole('button', { name: 'Send message' }).click();
81	
82	            await expect(page.getByText('Confirm your email')).toBeVisible({
83	                timeout: 15000,
84	            });
85	            await expect(
86	                page.getByRole('textbox', { name: 'Name' }),
87	            ).toHaveValue('');
88	            await expect(
89	                page.getByRole('textbox', { name: 'Email' }),
90	            ).toHaveValue('');
91	            await expect(
92	                page.getByRole('textbox', { name: 'Message' }),
93	            ).toHaveValue('');
94	
95	            const message = await waitForMessage(
96	                request,
97	                'Confirm your enquiry',
98	            );
99	            expect(
100	                message,
101	                'Expected verification email in Mailpit',
102	            ).toBeTruthy();
103	        });
104	
105	        test('completes full verification flow', async ({ page, request }) => {
106	            await page.goto('/footy/info');
107	            await page
108	                .getByRole('textbox', { name: 'Name' })
109	                .fill('Verification Tester');
110	            await page
111	                .getByRole('textbox', { name: 'Email' })
112	                .fill('verify@example.com');
113	            await page
114	                .getByRole('textbox', { name: 'Message' })
115	                .fill('Please verify this enquiry.');
116	            await page.getByRole('button', { name: 'Send message' }).click();
117	
118	            await expect(page.getByText('Confirm your email')).toBeVisible({
119	                timeout: 15000,
120	            });
121	
122	            const message = await waitForMessage(
123	                request,
124	                'Confirm your enquiry',
125	            );
126	            if (!message)
127	                throw new Error('Verification email not found in Mailpit');
128	
129	            const detail = await getMessageDetail(request, message.ID);
130	            const body = detail.HTML ?? detail.Text ?? '';
131	            const verificationLink = extractVerificationLink(body);
132	            if (!verificationLink)
133	                throw new Error(
134	                    `Verification link not found in email body:\n${body}`,
135	                );
136	
137	            await page.goto(verificationLink);
138	            await expect(page).toHaveURL(/\/footy\/auth\/verify\/enquiry\//);
139	            // Firefox can briefly double-mount this static server-rendered
140	            // Notification during hydration (self-heals within ~1s); .first()
141	            // avoids the resulting strict-mode violation without weakening
142	            // the assertion, since the content itself never varies.
143	            await expect(
144	                page.getByText('Thanks for your message').first(),
145	            ).toBeVisible();
146	        });
147	    });
148	});
